<script setup lang="ts">import { onMounted, computed } from 'vue'; import { MessageSquareText, ArrowUpRight } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import { useResourcesStore } from '../stores/resources'; import { formatDate, formatTime } from '../composables/useFormat'; const store = useResourcesStore(); onMounted(() => store.loadMessages()); const grouped = computed(() => store.messages);</script>
<template><section class="page-content"><PageHeader eyebrow="消息处理" title="消息" description="查看哪些消息被识别、哪些消息生成了任务。"><button class="button button-secondary" @click="store.loadMessages"><MessageSquareText :size="16" />刷新</button></PageHeader><section class="panel"><div class="list-heading"><strong>{{ grouped.length }} 条处理记录</strong><span class="muted-copy">只显示应用保留的结构化结果</span></div><div v-if="grouped.length" class="message-table"><article v-for="message in grouped" :key="message.id" class="message-card"><div class="message-icon"><MessageSquareText :size="17" /></div><div class="message-card-main"><div class="message-card-title"><strong>{{ message.had_task ? '已提取任务' : '已处理消息' }}</strong><span class="status-badge" :class="message.status">{{ message.status }}</span></div><p>{{ message.retained_text || '原文未保留，仅保存结构化处理结果。' }}</p><small>{{ formatDate(message.created_at) }} {{ formatTime(message.created_at) }} · 消息 #{{ message.id }}</small></div><ArrowUpRight :size="16" class="quiet-icon" /></article></div><EmptyState v-else title="还没有消息记录" description="连接消息源并启用自动提取后，这里会出现处理结果。" /></section></section></template>
